"use strict";

/* ---------- languages ---------- */

const LANGUAGES = [
  { code: "en", label: "English" },
  { code: "es", label: "Español" },
  { code: "nl", label: "Nederlands" },
  { code: "fr", label: "Français" },
  { code: "de", label: "Deutsch" },
  { code: "pap", label: "Papiamentu" },
];

const LANG_KEY = "macro-calc-lang";

function currentLang() {
  const l = document.documentElement.dataset.lang;
  return LANGUAGES.some((x) => x.code === l) ? l : "en";
}

function applyLang(code) {
  document.documentElement.dataset.lang = LANGUAGES.some((x) => x.code === code) ? code : "en";
}

/**
 * Resolves a translation-dictionary entry for the current language and
 * register. Entries are either a plain per-language string map, e.g.
 * { en: "Age", es: "Edad", ... }, or a per-language map of register pairs,
 * e.g. { en: {academic, conversational}, es: {...}, ... }. Missing
 * languages fall back to English so the UI never renders blank.
 */
function t(key) {
  const entry = I18N[key];
  if (!entry) return `[${key}]`;
  const langEntry = entry[currentLang()] || entry.en;
  if (typeof langEntry === "string") return langEntry;
  return langEntry[typeof currentRegister === "function" ? currentRegister() : "academic"] || langEntry.academic || langEntry.conversational || "";
}

/**
 * Like t(), but for entries whose academic/conversational values are
 * functions that need interpolation arguments (numbers, dates, etc.)
 * rather than plain strings, e.g. w_min_calories: { en: { academic: (min) => `...` } }.
 */
function tf(key, ...args) {
  const entry = I18N[key];
  if (!entry) return `[${key}]`;
  const langEntry = entry[currentLang()] || entry.en;
  const val = langEntry[typeof currentRegister === "function" ? currentRegister() : "academic"] || langEntry.academic || langEntry.conversational;
  return typeof val === "function" ? val(...args) : val || "";
}

