  good_notice: {
    en: { academic: (kcal) => `All three macronutrients fall within their evidence-based optimal ranges at a total daily intake of ${kcal} kcal. This is approximately the lowest energy level achievable here without moving a macronutrient outside its recommended range.`, conversational: (kcal) => `Every macro is in its sweet spot at just ${kcal} kcal a day. That's about as low as you can go here without pushing one of them out of its safe range.` },
    es: { academic: (kcal) => `Los tres macronutrientes están dentro de sus rangos óptimos basados en evidencia con una ingesta diaria total de ${kcal} kcal. Este es aproximadamente el nivel de energía más bajo alcanzable aquí sin sacar a un macronutriente de su rango recomendado.`, conversational: (kcal) => `Los tres macros están en su punto óptimo con solo ${kcal} kcal al día. Es más o menos lo más bajo que puedes llegar aquí sin sacar a uno de su rango seguro.` },
    nl: { academic: (kcal) => `Alle drie de macronutriënten vallen binnen hun onderbouwde optimale bereik bij een totale dagelijkse inname van ${kcal} kcal. Dit is ongeveer het laagste energieniveau dat hier haalbaar is zonder een macronutriënt buiten zijn aanbevolen bereik te brengen.`, conversational: (kcal) => `Elke macro zit in zijn sweet spot bij maar ${kcal} kcal per dag. Dat is ongeveer zo laag als je hier kunt komen zonder er eentje buiten zijn veilige bereik te duwen.` },
    fr: { academic: (kcal) => `Les trois macronutriments se situent dans leurs plages optimales fondées sur des preuves pour un apport quotidien total de ${kcal} kcal. C'est approximativement le niveau d'énergie le plus bas atteignable ici sans sortir un macronutriment de sa plage recommandée.`, conversational: (kcal) => `Les trois macros sont dans leur point optimal avec seulement ${kcal} kcal par jour. C'est à peu près le plus bas que vous puissiez descendre ici sans sortir l'un d'eux de sa plage sûre.` },
    de: { academic: (kcal) => `Alle drei Makronährstoffe liegen bei einer täglichen Gesamtzufuhr von ${kcal} kcal in ihrem evidenzbasierten optimalen Bereich. Das ist ungefähr das niedrigste hier erreichbare Energieniveau, ohne einen Makronährstoff aus seinem empfohlenen Bereich zu bringen.`, conversational: (kcal) => `Jede Makro liegt bei nur ${kcal} kcal am Tag in ihrem Sweet Spot. Das ist ungefähr so niedrig, wie du hier kommst, ohne eine aus ihrem sicheren Bereich zu drücken.` },
    pap: { academic: (kcal) => `Tur tres macronutriente ta kai den nan rango óptimo basá riba evidensia ku un konsumo diario total di ${kcal} kcal. Esaki ta mas o menos e nivel di energia mas abou alkansabel aki sin move un macronutriente pafó di su rango rekomendá.`, conversational: (kcal) => `Kada macro ta na su sweet spot ku djis ${kcal} kcal pa dia. Esei ta mas o menos e mas abou ku bo por yega aki sin pusha un pafó di su rango seguro.` },
  },
  muscle_tip: {
    en: { academic: `<strong>Muscle preservation:</strong> a caloric deficit spares muscle only when resistance training provides a physiological stimulus to retain it<sup class="cite"><a href="#ref-9">9</a></sup>. Resistance train 2 to 4 times weekly, meet the daily protein target across 3 to 5 meals, and obtain 7 to 9 hours of sleep.`, conversational: `<strong>Keep the muscle:</strong> a calorie deficit only spares muscle if you give your body a reason to keep it<sup class="cite"><a href="#ref-9">9</a></sup>. Do resistance training 2 to 4 times a week, hit your protein number daily (spread over 3 to 5 meals), and sleep 7 to 9 hours.` },
    es: { academic: `<strong>Preservación muscular:</strong> un déficit calórico conserva el músculo solo cuando el entrenamiento de resistencia proporciona un estímulo fisiológico para retenerlo<sup class="cite"><a href="#ref-9">9</a></sup>. Entrena fuerza de 2 a 4 veces por semana, cumple tu objetivo diario de proteína en 3 a 5 comidas, y duerme de 7 a 9 horas.`, conversational: `<strong>Conserva el músculo:</strong> un déficit de calorías solo conserva el músculo si le das a tu cuerpo un motivo para conservarlo<sup class="cite"><a href="#ref-9">9</a></sup>. Entrena fuerza de 2 a 4 veces por semana, cumple tu número de proteína cada día (repartido en 3 a 5 comidas), y duerme de 7 a 9 horas.` },
    nl: { academic: `<strong>Spierbehoud:</strong> een calorietekort spaart spieren alleen als krachttraining een fysiologische prikkel geeft om ze te behouden<sup class="cite"><a href="#ref-9">9</a></sup>. Doe 2 tot 4 keer per week krachttraining, haal je dagelijkse eiwitdoel over 3 tot 5 maaltijden, en slaap 7 tot 9 uur.`, conversational: `<strong>Behoud je spieren:</strong> een calorietekort spaart spieren alleen als je je lichaam een reden geeft om ze te behouden<sup class="cite"><a href="#ref-9">9</a></sup>. Doe 2 tot 4 keer per week krachttraining, haal je eiwitdoel elke dag (verdeeld over 3 tot 5 maaltijden), en slaap 7 tot 9 uur.` },
    fr: { academic: `<strong>Préservation musculaire :</strong> un déficit calorique n'épargne le muscle que lorsque l'entraînement de résistance fournit un stimulus physiologique pour le retenir<sup class="cite"><a href="#ref-9">9</a></sup>. Entraînez-vous en résistance 2 à 4 fois par semaine, atteignez l'objectif quotidien de protéines réparti sur 3 à 5 repas, et dormez 7 à 9 heures.`, conversational: `<strong>Gardez le muscle :</strong> un déficit calorique n'épargne le muscle que si vous donnez à votre corps une raison de le garder<sup class="cite"><a href="#ref-9">9</a></sup>. Faites de la musculation 2 à 4 fois par semaine, atteignez votre objectif de protéines chaque jour (réparti sur 3 à 5 repas), et dormez 7 à 9 heures.` },
    de: { academic: `<strong>Muskelerhalt:</strong> ein Kaloriendefizit schont Muskeln nur, wenn Krafttraining einen physiologischen Reiz zum Erhalt liefert<sup class="cite"><a href="#ref-9">9</a></sup>. Trainiere 2 bis 4 Mal wöchentlich Krafttraining, erreiche das tägliche Proteinziel über 3 bis 5 Mahlzeiten, und schlafe 7 bis 9 Stunden.`, conversational: `<strong>Muskeln behalten:</strong> ein Kaloriendefizit schont Muskeln nur, wenn du deinem Körper einen Grund gibst, sie zu behalten<sup class="cite"><a href="#ref-9">9</a></sup>. Mach 2 bis 4 Mal die Woche Krafttraining, erreiche dein Proteinziel jeden Tag (verteilt auf 3 bis 5 Mahlzeiten), und schlaf 7 bis 9 Stunden.` },
    pap: { academic: `<strong>Preservashon di músculo:</strong> un défisit kalóriko ta spar músculo solamente ora entrenamentu di resistensia ta duna un estímulo fisiológiko pa retené'e<sup class="cite"><a href="#ref-9">9</a></sup>. Hasi entrenamentu di forsa 2 pa 4 biaha pa siman, yega bo meta diario di proteina den 3 pa 5 kuminda, i drumi 7 pa 9 ora.`, conversational: `<strong>Warda bo músculo:</strong> un défisit di kaloria ta spar músculo solamente si bo duna bo kurpa un motibu pa warda'e<sup class="cite"><a href="#ref-9">9</a></sup>. Hasi entrenamentu di forsa 2 pa 4 biaha pa siman, yega bo number di proteina kada dia (parti riba 3 pa 5 kuminda), i drumi 7 pa 9 ora.` },
  },
